"""Gate policy: the machine-readable form of an agent's success check and anti-gaming rules."""
from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Dict, List, Optional

import yaml


@dataclass
class OracleSpec:
    command: List[str]
    timeout: int = 900
    must_contain: List[str] = field(default_factory=list)
    must_not_contain: List[str] = field(default_factory=list)


# Generated by tools, not authored by the model; excluded from the diff guard.
DEFAULT_IGNORE = [
    "**/__pycache__/**", "**/*.pyc", "**/.pytest_cache/**", "**/.mypy_cache/**",
    "**/node_modules/**", "**/target/**", "**/.lake/**", "**/*.o",
]


@dataclass
class GatePolicy:
    """Everything a hook or VERIFY needs to decide, with no model involvement.

    protected_paths: glob patterns relative to the workdir that may not change.
    forbidden_patterns: regexes that may not appear in added text.
    forbidden_commands: regexes a shell command may not match.
    output_schemas: output file (relative to workdir) -> JSON schema file.
    ignore_paths: build/cache output excluded from the diff guard (tool noise, not edits).
    confine_writes: block file writes outside the workdir.
    writable_paths: if non-empty, the only workdir-relative globs that may be written.
    hidden_paths: absolute globs the session may not read or search (the agent's spec and
        evaluation cases); a best-effort guard against reading the answers to its own tests.
    max_stop_blocks: how often the Stop hook may refuse to end a session.
    """

    oracle: Optional[OracleSpec] = None
    protected_paths: List[str] = field(default_factory=list)
    forbidden_patterns: List[str] = field(default_factory=list)
    forbidden_commands: List[str] = field(default_factory=list)
    output_schemas: Dict[str, str] = field(default_factory=dict)
    ignore_paths: List[str] = field(default_factory=lambda: list(DEFAULT_IGNORE))
    confine_writes: bool = True
    writable_paths: List[str] = field(default_factory=list)
    hidden_paths: List[str] = field(default_factory=list)
    max_stop_blocks: int = 3

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "GatePolicy":
        data = dict(data)
        oracle = data.pop("oracle", None)
        known = set(cls.__dataclass_fields__)
        unknown = sorted(set(data) - known)
        if unknown:
            raise ValueError("unknown gate policy fields: " + ", ".join(unknown))
        if oracle is not None:
            if isinstance(oracle, list):
                oracle = {"command": oracle}
            oracle = OracleSpec(**oracle)
            if not oracle.command:
                raise ValueError("oracle.command must be a non-empty argv list")
        return cls(oracle=oracle, **data)

    @classmethod
    def load(cls, path: Path) -> "GatePolicy":
        text = Path(path).read_text(encoding="utf-8")
        data = json.loads(text) if str(path).endswith(".json") else yaml.safe_load(text)
        return cls.from_dict(data or {})

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    def dump(self, path: Path) -> Path:
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(self.to_dict(), indent=2) + "\n", encoding="utf-8")
        return path
